# 2) Naive 2‑D convolution custom CUDA operator (float)
# ----------------------------------------------------------------------
conv2d_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(const float* input, const float* weight,
                               float* output,
                               int batch_size, int in_channels,
                               int out_channels,
                               int kernel_size, int stride, int padding, int dilation) {
    // Each thread computes one element of the output tensor.
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * out_channels * out_h * out_w) {   // out_h/out_w are known before launch
        // Decode linear index to (batch, out_channel, oy, ox)
        int tmp = idx;
        int b = tmp / (out_channels * out_h * out_w);
        tmp %= (out_channels * out_h * out_w);
        int oc = tmp / (out_h * out_w);
        tmp %= (out_h * out_w);
        int oy = tmp / out_w;
        int ox = tmp % out_w;

        float sum = 0.0f;
        for (int c = 0; c < in_channels; ++c) {
            // Input patch start coordinates
            int iy_start = oy * stride - padding + dilation * (dilation - 1) / 2;
            int ix_start = ox * stride - padding + dilation * (dilation - 1) / 2;

            for (int ky = -dilation/2; ky <= (in_h - 1)/stride - dilation/2; ++ky) {
                // Kernel offsets inside the patch
                for (int kx = -dilation/2; kx <= (in_w - 1)/stride - dilation/2; ++kx) {
                    int iy = oy * stride + ky * dilation;
                    int ix = ox * stride + kx * dilation;

                    if (iy < in_h && ix < in_w) {
                        float val_in = input[b*in_channels*in_h*in_w + c*in_h*in_w + iy*in_w + ix];
                        // weight layout: (out_channels, in_channels, kernel_size, kernel_size)
                        float val_w = weight[oc*kernel_size*kernel_size + c*kernel_size + ky*kernel_size + kx];
                        sum += val_in * val_w;
                    }
                }
            }
        }

        output[idx] = sum;
    }
}

torch::Tensor conv2d_cuda(torch::Tensor input, torch::Tensor weight) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto out_channels = weight.size(0);   // assuming weight shape (out_channels, in_channels, kH, kW)
    auto kernel_size = weight.size(2);     // square
    auto stride = 1;
    auto padding = 0;
    auto dilation = 1;
    auto groups = 1;

    int out_h = (input.size(2) + 2 * padding - kernel_size) / stride + 1;
    int out_w = (input.size(3) + 2 * padding - kernel_size) / stride + 1;

    auto out = torch::zeros(batch_size, out_channels, out_h, out_w);

    const int block_size = 256;
    const int num_blocks = (batch_size * out_channels * out_h * out_w + block_size - 1) / block_size;

    conv2d_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), weight.data_ptr<float>(), out.data_ptr<float>(), batch_size, in_channels, out_channels, kernel_size, stride, padding, dilation);

    return out;
}
"""

conv2d_source = "conv2d_cuda"

conv2d = load_inline(
    name="conv2d",
    cpp_sources=conv2d_source,
    cuda_sources=conv2d_kernel_source,
    functions=["conv2d_cuda"],
    verbose=True,
    extra_cflags=[],
