# ----------------------------------------------------------------------
# 3) Optimized model using the custom CUDA operators
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int = 16,
        out_channels: int = 128,
        kernel_size: int = 3,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False,
    ):
        super(ModelNew, self).__init__()
        # Keep the original Conv2d for weight extraction (needed by conv2d_cuda)
        self.conv2d_orig = nn.Conv2d(
            in_channels,
            out_channels,
            (kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )
        # Replace the convolution with our custom CUDA operator
        self.conv2d_cuda = conv2d

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height, width).
        Returns:
            Output tensor after 2‑D convolution using the custom CUDA kernel.
        """
        return self.conv2d_cuda(x, self.conv2d_orig.weight)
